def count_islands(grid) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    islands = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '#' or (r, c) in visited:
                continue

            islands += 1
            stack = [(r, c)]
            visited.add((r, c))

            while stack:
                cr, cc = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if (
                        0 <= nr < rows
                        and 0 <= nc < cols
                        and grid[nr][nc] == '#'
                        and (nr, nc) not in visited
                    ):
                        visited.add((nr, nc))
                        stack.append((nr, nc))

    return islands
